mapper.select:
select t.factory_id factoryId, t.factory_name factoryName, t.bean_impl beanImpl, t.remark, t.create_time createTime, t.status_cd statusCd, ifs.spec_id specId, ifs.factory_id factoryId1, ifs.spec_name specName, ifs.spec_cd specCd, ifs.remark remark1, ifs.create_time createTime1, ifs.status_cd statusCd1 from instrument_factory t left join instrument_factory_spec ifs on t.factory_id = ifs.factory_id and ifs.status_cd = '0' where 1 =1
and t.factory_id like concat('%', #{factoryId}, '%')
and t.factory_name like concat('%', #{factoryName}, '%')
and t.remark= #{remark}
and t.status_cd= #{statusCd}
and t.bean_impl like concat('%', #{beanImpl}, '%')
order by t.create_time desc
limit #{page}, #{row}

